INSERT INTO `parrafos` (`id`, `id_subtitulo`, `contenido`, `status`, `created_at`, `updated_at`) VALUES
(1,	3,	'Fortalecen el sistema inmune: Aportan vitaminas A, C y K, y minerales como zinc, hierro y calcio, que son esenciales para las defensas del cuerpo. \r\nDesintoxican el cuerpo: Contribuyen a eliminar toxinas del cuerpo y a la salud del hígado e intestinos. \r\nMejoran la salud intestinal: La fibra presente en los jugos verdes, especialmente si no se cuelan, favorece el tránsito intestinal y alimenta a las bacterias buenas del intestino. \r\nAumentan la energía: Proporcionan un impulso de energía natural, sin la necesidad de estimulantes artificiales.',	'1',	'2025-10-28 16:57:41',	'2025-10-28 16:57:41');
